283→// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
284→func (a *OpenCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
285→	session, err := ParseExportSession(transcriptData)
286→	if err != nil {
287→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
288→	}
289→	if session == nil {
290→		return nil, nil //nolint:nilnil // nil usage for empty data is expected
291→	}
292→
293→	usage := &agent.TokenUsage{}
294→	for i := fromOffset; i < len(session.Messages); i++ {
295→		msg := session.Messages[i]
296→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
297→			continue
298→		}
299→		usage.InputTokens += msg.Info.Tokens.Input
300→		usage.OutputTokens += msg.Info.Tokens.Output
301→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
302→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
303→		usage.APICallCount++
304→	}
305→
306→	return usage, nil
307→}
