134→// PrepareTranscript waits for Cursor's transcript file to be flushed to disk.
135→// Cursor writes transcripts asynchronously; during mid-turn commits the file
136→// may not yet contain data. This polls until the file exists and is non-empty,
137→// or until the timeout expires.
138→func (c *CursorAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
139→	const (
140→		maxWait      = 3 * time.Second
141→		pollInterval = 50 * time.Millisecond
142→	)
