134→// PrepareTranscript waits for Cursor's transcript file to be flushed to disk.
135→// Cursor writes transcripts asynchronously; during mid-turn commits the file
136→// may not yet contain data. This polls until the file exists and is non-empty,
137→// or until the timeout expires.
138→func (c *CursorAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
139→	const (
140→		maxWait      = 3 * time.Second
141→		pollInterval = 50 * time.Millisecond
142→	)
143→
144→	logCtx := logging.WithComponent(ctx, "agent.cursor")
145→
146→	deadline := time.Now().Add(maxWait)
147→	for time.Now().Before(deadline) {
148→		info, err := os.Stat(sessionRef)
149→		if err == nil {
150→			if info.Size() > 0 {
151→				logging.Debug(logCtx, "transcript file ready",
152→					slog.Int64("size", info.Size()),
153→				)
154→				return nil
155→			}
156→		} else if !os.IsNotExist(err) {
157→			return fmt.Errorf("failed to stat transcript %q: %w", sessionRef, err)
158→		}
159→		time.Sleep(pollInterval)
160→	}
161→
162→	logging.Warn(logCtx, "transcript file not ready within timeout, proceeding",
163→		slog.Duration("timeout", maxWait),
164→		slog.String("path", sessionRef),
165→	)
166→	return nil
167→}
168→
169→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
170→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
171→	if session == nil {
172→		return errors.New("session is nil")
173→	}
174→
175→	if session.AgentName != "" && session.AgentName != c.Name() {
176→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
177→	}
178→
179→	if session.SessionRef == "" {
180→		return errors.New("session reference (transcript path) is required")
181→	}
182→
183→	if len(session.NativeData) == 0 {
184→		return errors.New("session has no native data to write")
185→	}
186→
187→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
188→		return fmt.Errorf("failed to write transcript: %w", err)
189→	}
190→
191→	return nil
192→}
