144→func configureDroidRepoSettings(repoDir string) error {
145→	home, err := os.UserHomeDir()
146→	if err != nil {
147→		return fmt.Errorf("get home dir: %w", err)
148→	}
149→
150→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
151→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
152→
153→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
154→		return err
155→	}
156→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
157→		return fmt.Errorf("exclude droid settings from git: %w", err)
158→	}
159→	return nil
160→}
161→
162→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
163→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
164→	if err != nil {
165→		return err
166→	}
167→
168→	customModels, ok := globalSettings["customModels"]
169→	if !ok {
170→		return fmt.Errorf(
171→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
172→			globalSettingsPath,
173→			repoSettingsPath,
174→		)
175→	}
176→
177→	var models []json.RawMessage
178→	if err := json.Unmarshal(customModels, &models); err != nil {
179→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
180→	}
181→	if len(models) == 0 {
182→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
183→	}
184→
185→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
186→	if err != nil {
187→		return err
188→	}
189→	repoSettings["customModels"] = customModels
190→
191→	// Set the active custom model so interactive mode uses the BYOK model
192→	// instead of prompting for selection. The value must match the Model
193→	// field from the customModels entry (not the displayName).
194→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
195→	if err != nil {
196→		return fmt.Errorf("marshal model setting: %w", err)
197→	}
198→	repoSettings["model"] = json.RawMessage(modelJSON)
199→
200→	// High autonomy prevents Droid from asking for confirmation during
201→	// interactive E2E tests, which would cause hangs waiting for input.
202→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
203→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
204→
205→	out, err := json.MarshalIndent(repoSettings, "", "  ")
206→	if err != nil {
207→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
208→	}
209→	out = append(out, '\n')
210→
211→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
212→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
213→	}
214→	return nil
215→}
216→
217→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
218→	data, err := os.ReadFile(path)
219→	if err != nil {
220→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
221→	}
222→
223→	var parsed map[string]json.RawMessage
224→	if err := json.Unmarshal(data, &parsed); err != nil {
225→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
226→	}
227→	if parsed == nil {
228→		parsed = make(map[string]json.RawMessage)
229→	}
230→	return parsed, nil
231→}
