233→func ensureGitInfoExcludeContains(repoDir, entry string) error {
234→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
235→
236→	data, err := os.ReadFile(excludePath)
237→	if err != nil && !errors.Is(err, os.ErrNotExist) {
238→		return fmt.Errorf("read %s: %w", excludePath, err)
239→	}
240→
241→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
242→	for _, line := range strings.Split(normalized, "\n") {
243→		if strings.TrimSpace(line) == entry {
244→			return nil
245→		}
246→	}
247→
248→	var b strings.Builder
249→	if len(data) > 0 {
250→		b.Write(data)
251→		if data[len(data)-1] != '\n' {
252→			b.WriteByte('\n')
253→		}
254→	}
255→	b.WriteString(entry)
256→	b.WriteByte('\n')
257→
258→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
259→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
260→	}
261→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
262→		return fmt.Errorf("write %s: %w", excludePath, err)
263→	}
264→	return nil
265→}
