267→// ForEachAgent runs fn as a parallel subtest for every registered agent.
268→// It handles repo setup, concurrency gating, context timeout, and cleanup.
269→// The timeout is scaled by each agent's TimeoutMultiplier.
270→//
271→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
272→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
273→// panic and restarts the entire scenario with a fresh repository, up to
274→// maxScenarioRestarts times. This avoids stale CLI session state from the
275→// failed attempt poisoning the retry.
276→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
277→	t.Helper()
278→	t.Parallel()
279→	all := agents.All()
280→	if len(all) == 0 {
281→		t.Skip("no agents registered (check E2E_AGENT filter)")
282→	}
283→	for _, agent := range all {
284→		t.Run(agent.Name(), func(t *testing.T) {
285→			// Use the global test deadline for slot wait so we don't
286→			// skip prematurely — only bail if the whole binary is dying.
287→			slotCtx := context.Background()
288→			if deadline, ok := t.Deadline(); ok {
289→				var cancel context.CancelFunc
290→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
291→				defer cancel()
292→			}
293→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
294→				t.Fatalf("timed out waiting for agent slot: %v", err)
295→			}
296→			defer agents.ReleaseSlot(agent)
297→
298→			// Per-test timeout starts after slot is acquired, scaled
299→			// by the agent's multiplier (e.g. 2.5× for gemini).
300→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
301→
302→			var prevState *RepoState
303→			for attempt := range maxScenarioRestarts + 1 {
304→				s := SetupRepo(t, agent)
305→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
306→
307→				// On restart, suppress artifact capture from the previous
308→				// failed attempt so it doesn't overwrite the final one.
309→				if prevState != nil {
310→					prevState.skipArtifacts = true
311→				}
312→
313→				restarted := runScenario(t, s, ctx, fn)
314→				cancel()
315→
316→				if !restarted {
317→					return
318→				}
319→				prevState = s
320→				if attempt >= maxScenarioRestarts {
321→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
322→				}
323→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
324→			}
325→		})
326→	}
327→}
328→
329→// runScenario runs the test function and recovers from errScenarioRestart
330→// panics triggered by transient API errors in RunPrompt. Returns true if
331→// the scenario should be restarted with a fresh repository.
332→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
333→	t.Helper()
334→	defer func() {
335→		if r := recover(); r != nil {
336→			if _, ok := r.(errScenarioRestart); ok {
337→				restarted = true
338→				return
339→			}
340→			panic(r) // re-panic for unexpected panics
341→		}
342→	}()
343→	fn(t, s, ctx)
344→	return false
345→}
346→
347→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
348→
349→// errScenarioRestart is panicked by RunPrompt when a transient API error is
350→// detected. ForEachAgent recovers from this panic and restarts the test
351→// scenario with a fresh repository, avoiding stale CLI state from the failed
352→// attempt.
353→type errScenarioRestart struct {
354→	msg string
355→}
356→
357→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
358→// and returns the result. If the agent reports a transient API error, it
359→// panics with errScenarioRestart to trigger a full scenario restart in
360→// ForEachAgent (see runScenario).
361→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
362→	t.Helper()
363→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
364→	s.logPromptResult(out)
365→
366→	if err != nil && s.Agent.IsTransientError(out, err) {
