509→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
510→// checkpoint branch. It parses the two-level directory structure
511→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
512→func CheckpointIDs(t *testing.T, dir string) []string {
