519→	var ids []string
520→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
521→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
522→		parts := strings.Split(line, "/")
523→		if len(parts) == 3 && parts[2] == "metadata.json" {
524→			id := parts[0] + parts[1]
525→			if !seen[id] {
526→				seen[id] = true
527→				ids = append(ids, id)
528→			}
529→		}
530→	}
531→	return ids
532→}
