570→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
571→// branch for the given checkpoint ID and session index, then returns it.
572→// This handles the race where the checkpoint branch advances before session
573→// metadata is fully committed.
574→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
575→	t.Helper()
576→
577→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
578→	blob := "entire/checkpoints/v1:" + path
579→
580→	deadline := time.Now().Add(timeout)
581→	for time.Now().Before(deadline) {
582→		raw := gitOutputSafe(dir, "show", blob)
583→		if raw != "" {
584→			var meta SessionMetadata
585→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
586→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
587→			}
588→			return meta
589→		}
590→		time.Sleep(500 * time.Millisecond)
591→	}
592→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
593→	return SessionMetadata{}
594→}
