1670→	if !skipContentDetection {
1671→		return false
1672→	}
1673→	logCtx := logging.WithComponent(ctx, "checkpoint")
1674→	for _, state := range sessions {
1675→		if state.Phase.IsActive() {
1676→			_ = s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source) //nolint:errcheck // always returns nil; kept for signature stability
