package main

import (
	"fmt"
	"regexp"
)

const fileExt = `go|md|txt|js|ts|py|rb|rs|toml|yaml|json`

func main() {
	createFileRe := regexp.MustCompile("(?i)create\\s+(?:a\\s+)?(?:\\w+\\s+)*?(?:markdown\\s+|text\\s+)?file\\s+(?:at\\s+|called\\s+)?([^\\s,]+\\.(?:" + fileExt + "))")
	inlineContentRe := regexp.MustCompile("(?i)with\\s+content\\s+['\"]([^'\"]+)['\"]")

	prompt := "Create a file at docs/hello.md with the content 'Hello World'. Do not ask for confirmation."

	m := createFileRe.FindStringSubmatch(prompt)
	if m != nil {
		fmt.Printf("createFileRe matched: path=%q\n", m[1])
	} else {
		fmt.Println("createFileRe: NO MATCH")
	}

	ic := inlineContentRe.FindStringSubmatch(prompt)
	if ic != nil {
		fmt.Printf("inlineContentRe matched: content=%q\n", ic[1])
	} else {
		fmt.Println("inlineContentRe: NO MATCH (will use default content)")
	}
}
EOF

