	t.Run("conversation_id fallback for subagent start", func(t *testing.T) {
		t.Parallel()
		input := `{"conversation_id": "conv-sub", "transcript_path": "/tmp/t.jsonl", "subagent_id": "s1", "task": "do something"}`

