func TestReadTranscript_Success(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()
	transcriptPath := writeSampleTranscript(t, tmpDir)

	ag := &CursorAgent{}
	data, err := ag.ReadTranscript(transcriptPath)
	if err != nil {
